pause_query:
BEGIN;SET LOCAL statement_timeout='5s';SET LOCAL lock_timeout='1s';SELECT pg_advisory_xact_lock(20261015,30);
DO $guard$ BEGIN
IF NOT EXISTS(SELECT 1 FROM cron.job WHERE jobid=30 AND jobname='zoi-enrich-hourly' AND active AND schedule='*/5 * * * *' AND md5(command)='2ade25bb2cc7e9ab304662844ca1acfa' AND octet_length(command)=560) THEN RAISE EXCEPTION 'enrichment_pause_contract_drift';END IF;
PERFORM cron.alter_job(30,active:=false);
IF NOT EXISTS(SELECT 1 FROM cron.job WHERE jobid=30 AND jobname='zoi-enrich-hourly' AND NOT active AND schedule='*/5 * * * *' AND md5(command)='2ade25bb2cc7e9ab304662844ca1acfa' AND octet_length(command)=560) THEN RAISE EXCEPTION 'enrichment_pause_unconfirmed';END IF;
END $guard$;
SELECT jsonb_build_object('job',(SELECT jsonb_build_object('id',jobid,'name',jobname,'active',active,'schedule',schedule,'command_md5',md5(command),'command_bytes',octet_length(command))FROM cron.job WHERE jobid=30),'admission',(SELECT value FROM zoi.delivery_state WHERE key='enrichment_admission_v1'),'reason','Hold new enrichment until shared hidden/vendor/event-media extraction defects pass independent counterexamples and exact deployed worker binding','at',clock_timestamp());COMMIT;
